{-# LANGUAGE OverloadedStrings #-}

module TDF.Catalog.Integrity
  ( applyCatalogIntegrity
  ) where

import Control.Monad (forM_)
import Data.Text (Text)
import Database.Persist.Sql (SqlPersistT, rawExecute)

-- These migrations are deliberately idempotent and contain no business-data
-- transformation. A no-op alias update invokes the target-integrity trigger
-- so pre-existing aliases are validated before startup continues.
-- They run only after every catalog table exists. Backfills and destructive
-- cutover operations live in separately reviewed production scripts.
applyCatalogIntegrity :: SqlPersistT IO ()
applyCatalogIntegrity = forM_ catalogIntegrityStatements (`rawExecute` [])

catalogIntegrityStatements :: [Text]
catalogIntegrityStatements =
  [ "ALTER TABLE workflow_definition DROP CONSTRAINT IF EXISTS workflow_definition_public_sensitivity_check"
  , "ALTER TABLE workflow_definition ADD CONSTRAINT workflow_definition_public_sensitivity_check CHECK (NOT (sensitive AND public_read)) NOT VALID"
  , "ALTER TABLE workflow_definition VALIDATE CONSTRAINT workflow_definition_public_sensitivity_check"
  , "ALTER TABLE workflow_definition DROP CONSTRAINT IF EXISTS workflow_definition_revision_check"
  , "ALTER TABLE workflow_definition ADD CONSTRAINT workflow_definition_revision_check CHECK (version>=1 AND cache_revision>=1) NOT VALID"
  , "ALTER TABLE workflow_definition VALIDATE CONSTRAINT workflow_definition_revision_check"
  , "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='fk_workflow_transition_required_permission') THEN ALTER TABLE workflow_transition ADD CONSTRAINT fk_workflow_transition_required_permission FOREIGN KEY (required_permission_id) REFERENCES security_permission(id) NOT VALID; END IF; END $$"
  , "ALTER TABLE workflow_transition VALIDATE CONSTRAINT fk_workflow_transition_required_permission"
  , "CREATE OR REPLACE FUNCTION catalog_validate_workflow_relation() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE from_workflow uuid; to_workflow uuid; state_workflow uuid; BEGIN IF TG_TABLE_NAME='workflow_transition' THEN IF NEW.from_state_id=NEW.to_state_id THEN RAISE EXCEPTION 'workflow transitions require distinct states' USING ERRCODE='23514'; END IF; SELECT workflow_id INTO from_workflow FROM workflow_state WHERE id=NEW.from_state_id; SELECT workflow_id INTO to_workflow FROM workflow_state WHERE id=NEW.to_state_id; IF from_workflow IS DISTINCT FROM NEW.workflow_id OR to_workflow IS DISTINCT FROM NEW.workflow_id THEN RAISE EXCEPTION 'workflow transition states must belong to the declared workflow' USING ERRCODE='23514'; END IF; IF NEW.effective_from IS NOT NULL AND NEW.effective_until IS NOT NULL AND NEW.effective_until<=NEW.effective_from THEN RAISE EXCEPTION 'workflow transition effective window is invalid' USING ERRCODE='23514'; END IF; ELSIF TG_TABLE_NAME='workflow_default_state' THEN SELECT workflow_id INTO state_workflow FROM workflow_state WHERE id=NEW.state_id; IF state_workflow IS DISTINCT FROM NEW.workflow_id THEN RAISE EXCEPTION 'workflow default state must belong to the declared workflow' USING ERRCODE='23514'; END IF; IF btrim(NEW.context)='' OR NEW.context !~ '^[a-z][a-z0-9-]{0,79}$' THEN RAISE EXCEPTION 'workflow default context is invalid' USING ERRCODE='23514'; END IF; ELSE IF btrim(NEW.capability_code)='' OR NEW.capability_code !~ '^[a-z][a-z0-9-]{0,79}$' THEN RAISE EXCEPTION 'workflow state capability code is invalid' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS catalog_validate_workflow_relation ON workflow_transition"
  , "CREATE TRIGGER catalog_validate_workflow_relation BEFORE INSERT OR UPDATE ON workflow_transition FOR EACH ROW EXECUTE FUNCTION catalog_validate_workflow_relation()"
  , "DROP TRIGGER IF EXISTS catalog_validate_workflow_default ON workflow_default_state"
  , "CREATE TRIGGER catalog_validate_workflow_default BEFORE INSERT OR UPDATE ON workflow_default_state FOR EACH ROW EXECUTE FUNCTION catalog_validate_workflow_relation()"
  , "DROP TRIGGER IF EXISTS catalog_validate_workflow_capability ON workflow_state_capability"
  , "CREATE TRIGGER catalog_validate_workflow_capability BEFORE INSERT OR UPDATE ON workflow_state_capability FOR EACH ROW EXECUTE FUNCTION catalog_validate_workflow_relation()"
  , "CREATE OR REPLACE FUNCTION catalog_protect_workflow_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME='workflow_definition' THEN IF NEW.code IS DISTINCT FROM OLD.code THEN RAISE EXCEPTION 'workflow definition codes are immutable' USING ERRCODE='23514'; END IF; IF OLD.active AND NOT NEW.active AND (EXISTS (SELECT 1 FROM workflow_state state JOIN social_event event ON event.workflow_state_id=state.id WHERE state.workflow_id=OLD.id) OR EXISTS (SELECT 1 FROM pipeline_workflow_binding binding WHERE binding.workflow_id=OLD.id AND binding.active) OR EXISTS (SELECT 1 FROM workflow_state state JOIN ddex_document item ON item.workflow_state_id=state.id WHERE state.workflow_id=OLD.id) OR EXISTS (SELECT 1 FROM workflow_state state JOIN ddex_validation_run item ON item.workflow_state_id=state.id WHERE state.workflow_id=OLD.id) OR EXISTS (SELECT 1 FROM workflow_state state JOIN ddex_import_plan item ON item.workflow_state_id=state.id WHERE state.workflow_id=OLD.id) OR EXISTS (SELECT 1 FROM workflow_state state JOIN ddex_import_run item ON item.workflow_state_id=state.id WHERE state.workflow_id=OLD.id) OR EXISTS (SELECT 1 FROM workflow_state state JOIN ddex_export item ON item.workflow_state_id=state.id WHERE state.workflow_id=OLD.id) OR EXISTS (SELECT 1 FROM workflow_state state JOIN ddex_job item ON item.workflow_state_id=state.id WHERE state.workflow_id=OLD.id)) THEN RAISE EXCEPTION 'a referenced workflow cannot be deactivated' USING ERRCODE='23514'; END IF; ELSE IF NEW.workflow_id IS DISTINCT FROM OLD.workflow_id OR NEW.code IS DISTINCT FROM OLD.code THEN RAISE EXCEPTION 'workflow state workflow and code are immutable' USING ERRCODE='23514'; END IF; IF OLD.active AND NOT NEW.active AND (EXISTS (SELECT 1 FROM social_event event WHERE event.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM pipeline_card card WHERE card.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM ddex_document item WHERE item.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM ddex_validation_run item WHERE item.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM ddex_import_plan item WHERE item.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM ddex_import_run item WHERE item.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM ddex_export item WHERE item.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM ddex_job item WHERE item.workflow_state_id=OLD.id) OR EXISTS (SELECT 1 FROM workflow_default_state default_state WHERE default_state.state_id=OLD.id AND default_state.active) OR EXISTS (SELECT 1 FROM workflow_transition transition WHERE transition.active AND (transition.from_state_id=OLD.id OR transition.to_state_id=OLD.id)) OR EXISTS (SELECT 1 FROM workflow_state_capability capability WHERE capability.state_id=OLD.id AND capability.enabled)) THEN RAISE EXCEPTION 'a referenced workflow state cannot be deactivated' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS catalog_protect_workflow_identity ON workflow_definition"
  , "CREATE TRIGGER catalog_protect_workflow_identity BEFORE UPDATE ON workflow_definition FOR EACH ROW EXECUTE FUNCTION catalog_protect_workflow_identity()"
  , "DROP TRIGGER IF EXISTS catalog_protect_workflow_state_identity ON workflow_state"
  , "CREATE TRIGGER catalog_protect_workflow_state_identity BEFORE UPDATE ON workflow_state FOR EACH ROW EXECUTE FUNCTION catalog_protect_workflow_identity()"
