  , "CREATE OR REPLACE FUNCTION catalog_validate_pipeline_workflow_binding() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM service_offering service WHERE service.id=NEW.service_offering_id AND service.active) OR NOT EXISTS (SELECT 1 FROM workflow_definition workflow WHERE workflow.id=NEW.workflow_id AND workflow.active AND workflow.code LIKE 'pipeline-%') THEN RAISE EXCEPTION 'pipeline bindings require an active service offering and pipeline workflow' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS catalog_pipeline_workflow_binding_integrity ON pipeline_workflow_binding"
  , "CREATE TRIGGER catalog_pipeline_workflow_binding_integrity BEFORE INSERT OR UPDATE OF service_offering_id, workflow_id, active ON pipeline_workflow_binding FOR EACH ROW EXECUTE FUNCTION catalog_validate_pipeline_workflow_binding()"
  , "CREATE OR REPLACE FUNCTION catalog_protect_pipeline_binding() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.active AND NOT NEW.active AND EXISTS (SELECT 1 FROM pipeline_card card WHERE card.service_offering_id=OLD.service_offering_id) THEN RAISE EXCEPTION 'a pipeline binding referenced by cards cannot be deactivated' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS catalog_pipeline_workflow_binding_deactivation ON pipeline_workflow_binding"
  , "CREATE TRIGGER catalog_pipeline_workflow_binding_deactivation BEFORE UPDATE OF active ON pipeline_workflow_binding FOR EACH ROW EXECUTE FUNCTION catalog_protect_pipeline_binding()"
  , "CREATE OR REPLACE FUNCTION catalog_protect_pipeline_service_offering() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.active AND NOT NEW.active AND (EXISTS (SELECT 1 FROM pipeline_workflow_binding binding WHERE binding.service_offering_id=OLD.id AND binding.active) OR EXISTS (SELECT 1 FROM pipeline_card card WHERE card.service_offering_id=OLD.id)) THEN RAISE EXCEPTION 'a service offering used by an active pipeline must be replaced before deactivation' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
