  , "CREATE TRIGGER catalog_pipeline_service_offering_deactivation BEFORE UPDATE OF active ON service_offering FOR EACH ROW EXECUTE FUNCTION catalog_protect_pipeline_service_offering()"
  , "CREATE OR REPLACE FUNCTION catalog_validate_pipeline_card() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE workflow_id_value uuid; current_workflow_id uuid; BEGIN IF NEW.service_kind IS NOT NULL OR NEW.stage IS NOT NULL THEN RAISE EXCEPTION 'pipeline cards require canonical service_offering_id and workflow_state_id; legacy strings are migration evidence only' USING ERRCODE='23514'; END IF; IF NEW.service_offering_id IS NULL OR NEW.workflow_state_id IS NULL THEN RAISE EXCEPTION 'pipeline cards require service_offering_id and workflow_state_id' USING ERRCODE='23514'; END IF; SELECT binding.workflow_id INTO workflow_id_value FROM pipeline_workflow_binding binding JOIN service_offering service ON service.id=binding.service_offering_id AND service.active JOIN workflow_definition workflow ON workflow.id=binding.workflow_id AND workflow.active WHERE binding.service_offering_id=NEW.service_offering_id AND binding.active; IF workflow_id_value IS NULL OR NOT EXISTS (SELECT 1 FROM workflow_state state WHERE state.id=NEW.workflow_state_id AND state.workflow_id=workflow_id_value AND state.active) THEN RAISE EXCEPTION 'pipeline card state must belong to the active workflow bound to its service offering' USING ERRCODE='23514'; END IF; IF TG_OP='UPDATE' AND OLD.workflow_state_id IS NOT NULL AND NEW.workflow_state_id IS DISTINCT FROM OLD.workflow_state_id THEN SELECT state.workflow_id INTO current_workflow_id FROM workflow_state state WHERE state.id=OLD.workflow_state_id; IF current_workflow_id IS DISTINCT FROM workflow_id_value OR NOT EXISTS (SELECT 1 FROM workflow_transition transition WHERE transition.workflow_id=workflow_id_value AND transition.from_state_id=OLD.workflow_state_id AND transition.to_state_id=NEW.workflow_state_id AND transition.active AND transition.required_permission_id IS NULL AND NOT transition.requires_review AND NOT transition.requires_distinct_approver AND (transition.effective_from IS NULL OR transition.effective_from<=CURRENT_TIMESTAMP) AND (transition.effective_until IS NULL OR transition.effective_until>CURRENT_TIMESTAMP)) THEN RAISE EXCEPTION 'pipeline workflow transition is not allowed for direct execution' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS catalog_pipeline_card_integrity ON pipeline_card"
  , "CREATE TRIGGER catalog_pipeline_card_integrity BEFORE INSERT OR UPDATE OF service_kind, service_offering_id, stage, workflow_state_id ON pipeline_card FOR EACH ROW EXECUTE FUNCTION catalog_validate_pipeline_card()"
