  , "CREATE OR REPLACE FUNCTION catalog_validate_ddex_document() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE lifecycle_workflow_id uuid; BEGIN IF NEW.standard_version_id IS NULL OR NEW.workflow_state_id IS NULL THEN RAISE EXCEPTION 'DDEX documents require canonical standardVersionId and workflowStateId' USING ERRCODE='23502'; END IF; IF NEW.family IS NOT NULL OR NEW.version IS NOT NULL OR NEW.message_type IS NOT NULL OR NEW.status IS NOT NULL THEN RAISE EXCEPTION 'DDEX documents reject legacy family, version, messageType, and status strings' USING ERRCODE='23514'; END IF; IF NOT EXISTS (SELECT 1 FROM ddex_standard_version standard JOIN ddex_standard_support support ON support.standard_version_id=standard.id WHERE standard.id=NEW.standard_version_id AND standard.active AND support.deployment_code='default' AND support.active AND support.detection_enabled) THEN RAISE EXCEPTION 'DDEX document standard version is not active and detection-enabled' USING ERRCODE='23514'; END IF; IF NEW.message_type_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ddex_message_type message WHERE message.id=NEW.message_type_id AND message.standard_version_id=NEW.standard_version_id AND message.active AND message.runtime_supported) THEN RAISE EXCEPTION 'DDEX message type must be active, runtime-supported, and belong to the document standard version' USING ERRCODE='23514'; END IF; SELECT workflow.id INTO lifecycle_workflow_id FROM workflow_definition workflow JOIN workflow_state state ON state.workflow_id=workflow.id WHERE workflow.code='ddex-document-lifecycle' AND workflow.active AND state.id=NEW.workflow_state_id AND state.active; IF lifecycle_workflow_id IS NULL THEN RAISE EXCEPTION 'DDEX document state must belong to ddex-document-lifecycle' USING ERRCODE='23514'; END IF; IF TG_OP='UPDATE' AND OLD.workflow_state_id IS NOT NULL AND NEW.workflow_state_id IS DISTINCT FROM OLD.workflow_state_id AND NOT EXISTS (SELECT 1 FROM workflow_transition transition WHERE transition.workflow_id=lifecycle_workflow_id AND transition.from_state_id=OLD.workflow_state_id AND transition.to_state_id=NEW.workflow_state_id AND transition.active AND transition.required_permission_id IS NULL AND NOT transition.requires_review AND NOT transition.requires_distinct_approver AND (transition.effective_from IS NULL OR transition.effective_from<=CURRENT_TIMESTAMP) AND (transition.effective_until IS NULL OR transition.effective_until>CURRENT_TIMESTAMP)) THEN RAISE EXCEPTION 'DDEX document workflow transition is not allowed' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS ddex_document_canonical_integrity ON ddex_document"
  , "CREATE TRIGGER ddex_document_canonical_integrity BEFORE INSERT OR UPDATE ON ddex_document FOR EACH ROW EXECUTE FUNCTION catalog_validate_ddex_document()"
  , "CREATE OR REPLACE FUNCTION catalog_validate_ddex_partner_standard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.active AND (NOT EXISTS (SELECT 1 FROM ddex_partner partner WHERE partner.id=NEW.partner_id AND partner.is_active) OR NOT EXISTS (SELECT 1 FROM ddex_standard_version standard JOIN ddex_standard_support support ON support.standard_version_id=standard.id WHERE standard.id=NEW.standard_version_id AND standard.active AND support.deployment_code='default' AND support.active AND support.detection_enabled)) THEN RAISE EXCEPTION 'DDEX partner policy requires an active partner and detection-enabled governed standard version' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS ddex_partner_standard_integrity ON ddex_partner_standard_version"
  , "CREATE TRIGGER ddex_partner_standard_integrity BEFORE INSERT OR UPDATE ON ddex_partner_standard_version FOR EACH ROW EXECUTE FUNCTION catalog_validate_ddex_partner_standard()"
  , "CREATE OR REPLACE FUNCTION catalog_validate_ddex_operational_state() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE expected_workflow text; current_workflow uuid; new_row jsonb; old_row jsonb; new_state uuid; old_state uuid; BEGIN new_row=to_jsonb(NEW); old_row=to_jsonb(OLD); new_state=NULLIF(new_row->>'workflow_state_id','')::uuid; old_state=NULLIF(old_row->>'workflow_state_id','')::uuid; expected_workflow=CASE TG_TABLE_NAME WHEN 'ddex_validation_run' THEN 'ddex-validation-lifecycle' WHEN 'ddex_import_plan' THEN 'ddex-import-plan-lifecycle' WHEN 'ddex_import_run' THEN 'ddex-import-run-lifecycle' WHEN 'ddex_job' THEN 'ddex-job-lifecycle' END; IF new_state IS NULL OR (TG_TABLE_NAME IN ('ddex_import_plan','ddex_import_run','ddex_job') AND new_row->>'status' IS NOT NULL) OR (TG_TABLE_NAME='ddex_job' AND (new_row->>'operation_id' IS NULL OR new_row->>'job_type' IS NOT NULL)) THEN RAISE EXCEPTION 'DDEX operational rows require canonical workflow and operation IDs without legacy strings' USING ERRCODE='23514'; END IF; SELECT workflow.id INTO current_workflow FROM workflow_state state JOIN workflow_definition workflow ON workflow.id=state.workflow_id WHERE state.id=new_state AND state.active AND workflow.active AND workflow.code=expected_workflow; IF current_workflow IS NULL THEN RAISE EXCEPTION 'DDEX operational state belongs to the wrong lifecycle' USING ERRCODE='23514'; END IF; IF TG_TABLE_NAME='ddex_job' AND NOT EXISTS (SELECT 1 FROM ddex_job_operation operation WHERE operation.id=(new_row->>'operation_id')::uuid AND operation.active) THEN RAISE EXCEPTION 'DDEX job operation must be active' USING ERRCODE='23514'; END IF; IF TG_OP='UPDATE' AND old_state IS NOT NULL AND new_state IS DISTINCT FROM old_state AND NOT EXISTS (SELECT 1 FROM workflow_transition transition WHERE transition.workflow_id=current_workflow AND transition.from_state_id=old_state AND transition.to_state_id=new_state AND transition.active AND transition.required_permission_id IS NULL AND NOT transition.requires_review AND NOT transition.requires_distinct_approver) THEN RAISE EXCEPTION 'DDEX operational workflow transition is not allowed' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['ddex_validation_run','ddex_import_plan','ddex_import_run','ddex_job'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS ddex_operational_state_integrity ON %I',table_name); EXECUTE format('CREATE TRIGGER ddex_operational_state_integrity BEFORE INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION catalog_validate_ddex_operational_state()',table_name); END LOOP; END $$"
  , "CREATE OR REPLACE FUNCTION catalog_validate_ddex_import_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.operation_id IS NULL OR NEW.operation IS NOT NULL OR NOT EXISTS (SELECT 1 FROM ddex_import_operation operation WHERE operation.id=NEW.operation_id AND operation.active) THEN RAISE EXCEPTION 'DDEX import changes require an active canonical operation ID and reject legacy operation strings' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS ddex_import_change_canonical_integrity ON ddex_import_change"
  , "CREATE TRIGGER ddex_import_change_canonical_integrity BEFORE INSERT OR UPDATE ON ddex_import_change FOR EACH ROW EXECUTE FUNCTION catalog_validate_ddex_import_change()"
  , "CREATE OR REPLACE FUNCTION catalog_validate_ddex_validation_reference() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE row_data jsonb; BEGIN row_data=to_jsonb(NEW); IF TG_TABLE_NAME='ddex_validation_run' THEN IF row_data->>'result' IS NOT NULL OR ((row_data->>'finished_at') IS NOT NULL AND (row_data->>'result_id') IS NULL) OR ((row_data->>'result_id') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ddex_validation_result item WHERE item.id=(row_data->>'result_id')::uuid AND item.active)) THEN RAISE EXCEPTION 'DDEX validation runs require an active canonical result ID and reject legacy result constructors' USING ERRCODE='23514'; END IF; ELSIF TG_TABLE_NAME='ddex_validation_issue' THEN IF row_data->>'severity' IS NOT NULL OR row_data->>'layer' IS NOT NULL OR row_data->>'severity_id' IS NULL OR row_data->>'layer_id' IS NULL OR NOT EXISTS (SELECT 1 FROM ddex_validation_severity item WHERE item.id=(row_data->>'severity_id')::uuid AND item.active) OR NOT EXISTS (SELECT 1 FROM ddex_validation_layer item WHERE item.id=(row_data->>'layer_id')::uuid AND item.active) THEN RAISE EXCEPTION 'DDEX validation issues require active canonical severity and layer IDs and reject legacy constructors' USING ERRCODE='23514'; END IF; ELSIF TG_TABLE_NAME='ddex_export' AND (row_data->>'validation_result' IS NOT NULL OR ((row_data->>'validation_result_id') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ddex_validation_result item WHERE item.id=(row_data->>'validation_result_id')::uuid AND item.active))) THEN RAISE EXCEPTION 'DDEX exports reject legacy validation results and require an active canonical result ID' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS ddex_validation_reference_integrity ON ddex_validation_run"
  , "CREATE TRIGGER ddex_validation_reference_integrity BEFORE INSERT OR UPDATE ON ddex_validation_run FOR EACH ROW EXECUTE FUNCTION catalog_validate_ddex_validation_reference()"
  , "DROP TRIGGER IF EXISTS ddex_validation_reference_integrity ON ddex_validation_issue"
  , "CREATE TRIGGER ddex_validation_reference_integrity BEFORE INSERT OR UPDATE ON ddex_validation_issue FOR EACH ROW EXECUTE FUNCTION catalog_validate_ddex_validation_reference()"
  , "DROP TRIGGER IF EXISTS ddex_validation_reference_integrity ON ddex_export"
  , "CREATE TRIGGER ddex_validation_reference_integrity BEFORE INSERT OR UPDATE ON ddex_export FOR EACH ROW EXECUTE FUNCTION catalog_validate_ddex_validation_reference()"
  , "CREATE OR REPLACE FUNCTION catalog_prevent_referenced_ddex_validation_reference_deactivation() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE referenced boolean := false; BEGIN IF OLD.active AND NOT NEW.active THEN IF TG_TABLE_NAME='ddex_validation_result' THEN SELECT EXISTS (SELECT 1 FROM ddex_validation_run WHERE result_id=OLD.id UNION ALL SELECT 1 FROM ddex_export WHERE validation_result_id=OLD.id) INTO referenced; ELSIF TG_TABLE_NAME='ddex_validation_severity' THEN SELECT EXISTS (SELECT 1 FROM ddex_validation_issue WHERE severity_id=OLD.id) INTO referenced; ELSIF TG_TABLE_NAME='ddex_validation_layer' THEN SELECT EXISTS (SELECT 1 FROM ddex_validation_issue WHERE layer_id=OLD.id) INTO referenced; END IF; IF referenced THEN RAISE EXCEPTION 'referenced DDEX validation registry rows cannot be deactivated' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$"
  , "DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['ddex_validation_result','ddex_validation_severity','ddex_validation_layer'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS ddex_validation_reference_deactivation ON %I',table_name); EXECUTE format('CREATE TRIGGER ddex_validation_reference_deactivation BEFORE UPDATE OF active ON %I FOR EACH ROW EXECUTE FUNCTION catalog_prevent_referenced_ddex_validation_reference_deactivation()',table_name); END LOOP; END $$"
  , "CREATE OR REPLACE FUNCTION catalog_validate_ddex_export() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE lifecycle_workflow_id uuid; BEGIN IF NEW.standard_version_id IS NULL OR NEW.workflow_state_id IS NULL OR NEW.ern_version IS NOT NULL THEN RAISE EXCEPTION 'DDEX exports require canonical standardVersionId and workflowStateId and reject legacy version strings' USING ERRCODE='23514'; END IF; IF NOT EXISTS (SELECT 1 FROM ddex_standard_version standard JOIN ddex_standard_support support ON support.standard_version_id=standard.id JOIN ddex_partner_standard_version membership ON membership.standard_version_id=standard.id AND membership.partner_id=NEW.partner_id AND membership.active JOIN ddex_partner partner ON partner.id=membership.partner_id AND partner.is_active WHERE standard.id=NEW.standard_version_id AND standard.active AND support.deployment_code='default' AND support.active AND support.export_enabled) THEN RAISE EXCEPTION 'DDEX export requires an active partner policy and export-enabled standard version' USING ERRCODE='23514'; END IF; SELECT workflow.id INTO lifecycle_workflow_id FROM workflow_state state JOIN workflow_definition workflow ON workflow.id=state.workflow_id WHERE state.id=NEW.workflow_state_id AND state.active AND workflow.active AND workflow.code='ddex-export-lifecycle'; IF lifecycle_workflow_id IS NULL THEN RAISE EXCEPTION 'DDEX export state must belong to ddex-export-lifecycle' USING ERRCODE='23514'; END IF; IF TG_OP='UPDATE' AND OLD.workflow_state_id IS NOT NULL AND NEW.workflow_state_id IS DISTINCT FROM OLD.workflow_state_id AND NOT EXISTS (SELECT 1 FROM workflow_transition transition WHERE transition.workflow_id=lifecycle_workflow_id AND transition.from_state_id=OLD.workflow_state_id AND transition.to_state_id=NEW.workflow_state_id AND transition.active AND transition.required_permission_id IS NULL AND NOT transition.requires_review AND NOT transition.requires_distinct_approver) THEN RAISE EXCEPTION 'DDEX export workflow transition is not allowed' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
