  , "CREATE OR REPLACE FUNCTION catalog_validate_social_event_type() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.event_type_id IS NULL THEN RAISE EXCEPTION 'social events require event_type_id' USING ERRCODE='23514'; END IF; IF NEW.metadata IS NOT NULL AND NEW.metadata::jsonb ?? 'eventType' THEN RAISE EXCEPTION 'social events require event_type_id; metadata eventType strings are migration evidence only' USING ERRCODE='23514'; END IF; IF NOT EXISTS (SELECT 1 FROM event_type item JOIN catalog_definition catalog ON catalog.id=item.catalog_id AND catalog.code='event-types' AND catalog.active JOIN workflow_state state ON state.id=item.workflow_state_id AND state.workflow_id=catalog.workflow_id AND state.code='published' AND state.active WHERE item.id=NEW.event_type_id AND item.active AND item.deprecated_at IS NULL AND (item.effective_from IS NULL OR item.effective_from<=CURRENT_DATE) AND (item.effective_until IS NULL OR item.effective_until>=CURRENT_DATE)) THEN RAISE EXCEPTION 'social event requires an active effective published event type' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
