  , "CREATE OR REPLACE FUNCTION catalog_version_workflow_definition() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ROW(NEW.code,NEW.name_es,NEW.name_en,NEW.description_es,NEW.description_en,NEW.sensitive,NEW.public_read,NEW.active) IS DISTINCT FROM ROW(OLD.code,OLD.name_es,OLD.name_en,OLD.description_es,OLD.description_en,OLD.sensitive,OLD.public_read,OLD.active) THEN NEW.updated_at=CURRENT_TIMESTAMP; NEW.version=GREATEST(NEW.version,OLD.version+1); NEW.cache_revision=GREATEST(NEW.cache_revision,OLD.cache_revision+1); END IF; RETURN NEW; END $$"
