  , "CREATE OR REPLACE FUNCTION catalog_bump_workflow_revision() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE workflow_id_value uuid; BEGIN IF TG_TABLE_NAME='workflow_state_capability' THEN SELECT workflow_id INTO workflow_id_value FROM workflow_state WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.state_id ELSE NEW.state_id END; ELSIF TG_TABLE_NAME='workflow_state' THEN workflow_id_value=CASE WHEN TG_OP='DELETE' THEN OLD.workflow_id ELSE NEW.workflow_id END; ELSE workflow_id_value=CASE WHEN TG_OP='DELETE' THEN OLD.workflow_id ELSE NEW.workflow_id END; END IF; UPDATE workflow_definition SET cache_revision=cache_revision+1, updated_at=CURRENT_TIMESTAMP WHERE id=workflow_id_value; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$"
