  , "CREATE OR REPLACE FUNCTION catalog_bump_pipeline_workflow_revision() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE old_workflow_id uuid; new_workflow_id uuid; BEGIN IF TG_TABLE_NAME='pipeline_workflow_binding' THEN IF TG_OP<>'INSERT' THEN old_workflow_id=OLD.workflow_id; END IF; IF TG_OP<>'DELETE' THEN new_workflow_id=NEW.workflow_id; END IF; ELSE IF TG_OP<>'INSERT' THEN SELECT workflow_id INTO old_workflow_id FROM pipeline_workflow_binding WHERE service_offering_id=OLD.service_offering_id AND active; END IF; IF TG_OP<>'DELETE' THEN SELECT workflow_id INTO new_workflow_id FROM pipeline_workflow_binding WHERE service_offering_id=NEW.service_offering_id AND active; END IF; END IF; UPDATE workflow_definition SET cache_revision=cache_revision+1, updated_at=CURRENT_TIMESTAMP WHERE id IN (old_workflow_id,new_workflow_id); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$"
