  , "CREATE OR REPLACE FUNCTION catalog_validate_social_event_workflow_state() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE workflow_id_value uuid; BEGIN IF NEW.workflow_state_id IS NULL THEN RAISE EXCEPTION 'social events require workflow_state_id' USING ERRCODE='23514'; END IF; IF NEW.metadata IS NOT NULL AND NEW.metadata::jsonb ?? 'eventStatus' THEN RAISE EXCEPTION 'social events require workflow_state_id; metadata eventStatus strings are migration evidence only' USING ERRCODE='23514'; END IF; SELECT state.workflow_id INTO workflow_id_value FROM workflow_state state JOIN workflow_definition workflow ON workflow.id=state.workflow_id WHERE state.id=NEW.workflow_state_id AND state.active AND workflow.active AND workflow.code='social-event-lifecycle'; IF workflow_id_value IS NULL THEN RAISE EXCEPTION 'social event requires an active state in social-event-lifecycle' USING ERRCODE='23514'; END IF; IF TG_OP='UPDATE' AND OLD.workflow_state_id IS NOT NULL AND NEW.workflow_state_id IS DISTINCT FROM OLD.workflow_state_id AND NOT EXISTS (SELECT 1 FROM workflow_transition transition WHERE transition.workflow_id=workflow_id_value AND transition.from_state_id=OLD.workflow_state_id AND transition.to_state_id=NEW.workflow_state_id AND transition.active AND transition.required_permission_id IS NULL AND NOT transition.requires_review AND NOT transition.requires_distinct_approver AND (transition.effective_from IS NULL OR transition.effective_from<=CURRENT_TIMESTAMP) AND (transition.effective_until IS NULL OR transition.effective_until>CURRENT_TIMESTAMP)) THEN RAISE EXCEPTION 'social event workflow transition is not allowed for direct execution' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
