  , "CREATE OR REPLACE FUNCTION catalog_validate_feedback_references() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.category IS NOT NULL OR NEW.severity IS NOT NULL THEN RAISE EXCEPTION 'feedback requires category_id and severity_id; copied category and severity values are migration evidence only' USING ERRCODE='23514'; END IF; IF NEW.category_id IS NULL OR NOT EXISTS (SELECT 1 FROM feedback_category item JOIN catalog_definition catalog ON catalog.id=item.catalog_id AND catalog.code='feedback-categories' AND catalog.active JOIN workflow_state state ON state.id=item.workflow_state_id AND state.code='published' AND state.active WHERE item.id=NEW.category_id AND item.active AND item.deprecated_at IS NULL) THEN RAISE EXCEPTION 'feedback requires an active published category' USING ERRCODE='23514'; END IF; IF NEW.severity_id IS NULL OR NOT EXISTS (SELECT 1 FROM feedback_severity item JOIN catalog_definition catalog ON catalog.id=item.catalog_id AND catalog.code='feedback-severities' AND catalog.active JOIN workflow_state state ON state.id=item.workflow_state_id AND state.code='published' AND state.active WHERE item.id=NEW.severity_id AND item.active AND item.deprecated_at IS NULL) THEN RAISE EXCEPTION 'feedback requires an active published severity' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
