  , "CREATE OR REPLACE FUNCTION catalog_validate_user_preference_regional() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE locale_code text; currency_code text; BEGIN IF NEW.locale_id IS NULL OR NEW.currency_id IS NULL THEN RAISE EXCEPTION 'user preference requires canonical localeId and currencyId' USING ERRCODE='23502'; END IF; SELECT item.code INTO locale_code FROM locale_reference item JOIN deployment_locale_enablement enabled ON enabled.locale_id=item.id AND enabled.deployment_code='default' AND enabled.enabled WHERE item.id=NEW.locale_id AND item.active AND item.deprecated_at IS NULL; IF locale_code IS NULL THEN RAISE EXCEPTION 'user preference requires an active deployment-enabled locale' USING ERRCODE='23514'; END IF; SELECT item.code INTO currency_code FROM currency_reference item JOIN deployment_currency_enablement enabled ON enabled.currency_id=item.id AND enabled.deployment_code='default' AND enabled.enabled WHERE item.id=NEW.currency_id AND item.active AND item.deprecated_at IS NULL; IF currency_code IS NULL THEN RAISE EXCEPTION 'user preference requires an active deployment-enabled currency' USING ERRCODE='23514'; END IF; IF NEW.locale IS NOT NULL AND lower(btrim(NEW.locale))<>lower(locale_code) THEN RAISE EXCEPTION 'legacy locale evidence conflicts with localeId' USING ERRCODE='23514'; END IF; IF NEW.currency IS NOT NULL AND upper(btrim(NEW.currency))<>upper(currency_code) THEN RAISE EXCEPTION 'legacy currency evidence conflicts with currencyId' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
