  , "CREATE OR REPLACE FUNCTION catalog_validate_workflow_transition() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE from_workflow uuid; to_workflow uuid; BEGIN SELECT workflow_id INTO from_workflow FROM workflow_state WHERE id=NEW.from_state_id AND active; SELECT workflow_id INTO to_workflow FROM workflow_state WHERE id=NEW.to_state_id AND active; IF from_workflow IS DISTINCT FROM NEW.workflow_id OR to_workflow IS DISTINCT FROM NEW.workflow_id THEN RAISE EXCEPTION 'workflow transition states must belong to the declared workflow' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS workflow_transition_integrity ON workflow_transition"
  , "CREATE TRIGGER workflow_transition_integrity BEFORE INSERT OR UPDATE ON workflow_transition FOR EACH ROW EXECUTE FUNCTION catalog_validate_workflow_transition()"
  , "CREATE OR REPLACE FUNCTION catalog_validate_revision_workflow() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE expected_workflow uuid; actual_workflow uuid; BEGIN SELECT workflow_id INTO expected_workflow FROM catalog_definition WHERE id=NEW.catalog_id AND active; SELECT workflow_id INTO actual_workflow FROM workflow_state WHERE id=NEW.workflow_state_id AND active; IF expected_workflow IS NULL OR actual_workflow IS DISTINCT FROM expected_workflow THEN RAISE EXCEPTION 'catalog revision state must belong to the catalog workflow' USING ERRCODE='23514'; END IF; IF NEW.approved_by IS NOT NULL AND NEW.approved_by=NEW.created_by THEN RAISE EXCEPTION 'catalog change creators cannot approve their own change' USING ERRCODE='42501'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS catalog_revision_workflow_integrity ON catalog_revision"
  , "CREATE TRIGGER catalog_revision_workflow_integrity BEFORE INSERT OR UPDATE ON catalog_revision FOR EACH ROW EXECUTE FUNCTION catalog_validate_revision_workflow()"
  , "CREATE OR REPLACE FUNCTION catalog_validate_slug_alias_target() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE target_valid boolean := false; BEGIN CASE NEW.entity_kind WHEN 'authored_content' THEN SELECT EXISTS (SELECT 1 FROM authored_content target JOIN catalog_definition catalog ON catalog.id=NEW.catalog_id AND catalog.code='authored-content' WHERE target.id=NEW.entity_id) INTO target_valid; WHEN 'record-release' THEN SELECT EXISTS (SELECT 1 FROM record_release target WHERE target.id=NEW.entity_id AND target.catalog_id=NEW.catalog_id) INTO target_valid; WHEN 'recording' THEN SELECT EXISTS (SELECT 1 FROM recording target WHERE target.id=NEW.entity_id AND target.catalog_id=NEW.catalog_id) INTO target_valid; WHEN 'recording-session' THEN SELECT EXISTS (SELECT 1 FROM recording_session target WHERE target.id=NEW.entity_id AND target.catalog_id=NEW.catalog_id) INTO target_valid; ELSE RAISE EXCEPTION 'unsupported catalog slug alias entity kind: %',NEW.entity_kind USING ERRCODE='23514'; END CASE; IF NOT COALESCE(target_valid,false) THEN RAISE EXCEPTION 'catalog slug alias target does not exist in its declared catalog' USING ERRCODE='23503'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS catalog_slug_alias_target_integrity ON catalog_slug_alias"
  , "CREATE TRIGGER catalog_slug_alias_target_integrity BEFORE INSERT OR UPDATE OF catalog_id,entity_kind,entity_id ON catalog_slug_alias FOR EACH ROW EXECUTE FUNCTION catalog_validate_slug_alias_target()"
  , "UPDATE catalog_slug_alias SET entity_id=entity_id"
  , "CREATE OR REPLACE FUNCTION security_is_coherent_emergency_administrator(candidate_party bigint) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS (SELECT 1 FROM party_security_role assignment JOIN security_role role ON role.id=assignment.role_id AND role.active AND role.emergency_administrator JOIN user_credential credential ON credential.party_id=assignment.party_id AND credential.active WHERE assignment.party_id=candidate_party AND assignment.active AND NOT EXISTS (SELECT required.code FROM (VALUES ('admin.access'),('security.read'),('security.create'),('security.review'),('security.approve'),('security.assign'),('security.emergency-recover')) required(code) WHERE NOT EXISTS (SELECT 1 FROM role_permission grant_row JOIN security_permission permission ON permission.id=grant_row.permission_id AND permission.active JOIN security_action action ON action.id=permission.action_id AND action.active JOIN security_module module_row ON module_row.id=permission.module_id AND module_row.active WHERE grant_row.role_id=role.id AND grant_row.active AND permission.code=required.code))) $$"
  , "CREATE OR REPLACE FUNCTION security_validate_grant_revision() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE workflow_code text; actor_is_emergency boolean; BEGIN SELECT w.code INTO workflow_code FROM workflow_state s JOIN workflow_definition w ON w.id=s.workflow_id WHERE s.id=NEW.workflow_state_id AND s.active AND w.active; IF workflow_code IS DISTINCT FROM 'sensitive-publication' THEN RAISE EXCEPTION 'security grant revisions must use the sensitive publication workflow' USING ERRCODE='23514'; END IF; IF NEW.change_kind='party-role' THEN IF NEW.party_id IS NULL OR NEW.permission_id IS NOT NULL THEN RAISE EXCEPTION 'party-role revisions require party and role only' USING ERRCODE='23514'; END IF; ELSIF NEW.change_kind='role-permission' THEN IF NEW.party_id IS NOT NULL OR NEW.permission_id IS NULL THEN RAISE EXCEPTION 'role-permission revisions require role and permission only' USING ERRCODE='23514'; END IF; ELSE RAISE EXCEPTION 'unknown security grant revision kind' USING ERRCODE='23514'; END IF; IF NEW.expected_version<0 THEN RAISE EXCEPTION 'security grant expected version cannot be negative' USING ERRCODE='23514'; END IF; IF NEW.approval_mode NOT IN ('normal','emergency') THEN RAISE EXCEPTION 'invalid security revision approval mode' USING ERRCODE='23514'; END IF; IF NEW.approved_by IS NOT NULL AND NEW.approved_by=NEW.created_by THEN IF NEW.approval_mode<>'emergency' OR length(btrim(COALESCE(NEW.emergency_reason,'')))<20 THEN RAISE EXCEPTION 'security change creators require a documented emergency override to self-approve' USING ERRCODE='42501'; END IF; SELECT security_is_coherent_emergency_administrator(NEW.approved_by) INTO actor_is_emergency; IF NOT COALESCE(actor_is_emergency,FALSE) THEN RAISE EXCEPTION 'emergency override approver is not an active emergency administrator' USING ERRCODE='42501'; END IF; ELSIF NEW.approval_mode='emergency' THEN RAISE EXCEPTION 'emergency approval mode is valid only for documented self-approval' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS security_grant_revision_integrity ON security_grant_revision"
  , "CREATE TRIGGER security_grant_revision_integrity BEFORE INSERT OR UPDATE ON security_grant_revision FOR EACH ROW EXECUTE FUNCTION security_validate_grant_revision()"
  , "CREATE OR REPLACE FUNCTION catalog_validate_replacement() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE target_active boolean; BEGIN IF NEW.replacement_id IS NULL THEN RETURN NEW; END IF; IF NEW.replacement_id=NEW.id THEN RAISE EXCEPTION 'an item cannot replace itself' USING ERRCODE='23514'; END IF; EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I WHERE id=$1 AND active)', TG_TABLE_NAME) INTO target_active USING NEW.replacement_id; IF NOT target_active THEN RAISE EXCEPTION 'replacement target must exist and be active in %', TG_TABLE_NAME USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "CREATE OR REPLACE FUNCTION catalog_prevent_hierarchy_cycle() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE has_cycle boolean; BEGIN IF NEW.parent_id IS NULL THEN RETURN NEW; END IF; IF NEW.parent_id=NEW.id THEN RAISE EXCEPTION 'catalog hierarchy cannot reference itself' USING ERRCODE='23514'; END IF; EXECUTE format('WITH RECURSIVE ancestors(id,parent_id) AS (SELECT id,parent_id FROM %I WHERE id=$1 UNION ALL SELECT p.id,p.parent_id FROM %I p JOIN ancestors a ON p.id=a.parent_id) SELECT EXISTS (SELECT 1 FROM ancestors WHERE id=$2)', TG_TABLE_NAME, TG_TABLE_NAME) INTO has_cycle USING NEW.parent_id, NEW.id; IF has_cycle THEN RAISE EXCEPTION 'catalog hierarchy cycle detected in %', TG_TABLE_NAME USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['genre','instrument','service_category','content_category'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS catalog_hierarchy_cycle ON %I', table_name); EXECUTE format('CREATE TRIGGER catalog_hierarchy_cycle BEFORE INSERT OR UPDATE OF parent_id ON %I FOR EACH ROW EXECUTE FUNCTION catalog_prevent_hierarchy_cycle()', table_name); END LOOP; END $$"
  , "DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['release_type_reference','recording_type_reference','recording_session_type','service_category','service_pricing_model','service_offering','radio_auto_stop_option','appearance_mode_option','genre','instrument','event_type','booking_type','feedback_category','feedback_severity','content_category','tag','country_reference','subdivision_reference','city_reference','currency_reference','tax_rate_reference','language_reference','locale_reference','external_provider','external_provider_code','ddex_standard_version','ddex_message_type','ddex_vocabulary','ddex_code'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS catalog_replacement_integrity ON %I', table_name); EXECUTE format('CREATE TRIGGER catalog_replacement_integrity BEFORE INSERT OR UPDATE OF replacement_id ON %I FOR EACH ROW EXECUTE FUNCTION catalog_validate_replacement()', table_name); END LOOP; END $$"
  , "CREATE OR REPLACE FUNCTION catalog_prevent_hard_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'catalog and registry rows cannot be hard-deleted; deactivate, replace, merge, or reverse instead' USING ERRCODE='55000'; END $$"
