  , "CREATE OR REPLACE FUNCTION catalog_validate_radio_auto_stop_default() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.active AND NEW.scope_kind='radio-broadcast' THEN IF NEW.scope_id <> 'global' OR NEW.locale_id IS NOT NULL OR NOT EXISTS (SELECT 1 FROM catalog_definition catalog JOIN radio_auto_stop_option option ON option.catalog_id=catalog.id JOIN workflow_state state ON state.id=option.workflow_state_id AND state.workflow_id=catalog.workflow_id WHERE catalog.id=NEW.catalog_id AND catalog.entity_kind='radio_auto_stop_option' AND option.id=NEW.entity_id AND option.active AND option.deprecated_at IS NULL AND state.code='published' AND state.active) THEN RAISE EXCEPTION 'radio broadcast default must reference an active published non-deprecated radio auto-stop option'; END IF; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS catalog_radio_auto_stop_default_integrity ON catalog_scoped_default"
