  , "CREATE OR REPLACE FUNCTION catalog_validate_feedback_default() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE target_valid boolean := false; BEGIN IF NOT NEW.active OR NEW.scope_kind NOT IN ('feedback-category','feedback-severity') THEN RETURN NEW; END IF; IF NEW.scope_id<>'global' OR NEW.locale_id IS NOT NULL THEN RAISE EXCEPTION 'feedback defaults must use the global scope'; END IF; IF NEW.scope_kind='feedback-category' THEN SELECT EXISTS (SELECT 1 FROM catalog_definition catalog JOIN feedback_category item ON item.catalog_id=catalog.id JOIN workflow_state state ON state.id=item.workflow_state_id AND state.workflow_id=catalog.workflow_id WHERE catalog.id=NEW.catalog_id AND catalog.entity_kind='feedback_category' AND item.id=NEW.entity_id AND item.active AND item.deprecated_at IS NULL AND state.code='published' AND state.active) INTO target_valid; ELSE SELECT EXISTS (SELECT 1 FROM catalog_definition catalog JOIN feedback_severity item ON item.catalog_id=catalog.id JOIN workflow_state state ON state.id=item.workflow_state_id AND state.workflow_id=catalog.workflow_id WHERE catalog.id=NEW.catalog_id AND catalog.entity_kind='feedback_severity' AND item.id=NEW.entity_id AND item.active AND item.deprecated_at IS NULL AND state.code='published' AND state.active) INTO target_valid; END IF; IF NOT COALESCE(target_valid,false) THEN RAISE EXCEPTION 'feedback default must reference an active published non-deprecated option'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS catalog_feedback_default_integrity ON catalog_scoped_default"
