  , "CREATE OR REPLACE FUNCTION catalog_prevent_active_feedback_default_deactivation() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE expected_scope text; BEGIN expected_scope := CASE TG_TABLE_NAME WHEN 'feedback_category' THEN 'feedback-category' WHEN 'feedback_severity' THEN 'feedback-severity' ELSE NULL END; IF OLD.active AND NOT NEW.active AND expected_scope IS NOT NULL AND EXISTS (SELECT 1 FROM catalog_scoped_default scoped WHERE scoped.catalog_id=OLD.catalog_id AND scoped.entity_id=OLD.id AND scoped.scope_kind=expected_scope AND scoped.scope_id='global' AND scoped.locale_id IS NULL AND scoped.active) THEN RAISE EXCEPTION 'active feedback default cannot be deactivated'; END IF; RETURN NEW; END $$"
