  , "CREATE OR REPLACE FUNCTION catalog_validate_social_event_default() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT NEW.active OR NEW.scope_kind<>'social-event' THEN RETURN NEW; END IF; IF NEW.scope_id<>'global' OR NEW.locale_id IS NOT NULL OR NOT EXISTS (SELECT 1 FROM catalog_definition catalog JOIN event_type item ON item.catalog_id=catalog.id JOIN workflow_state state ON state.id=item.workflow_state_id AND state.workflow_id=catalog.workflow_id WHERE catalog.id=NEW.catalog_id AND catalog.entity_kind='event_type' AND item.id=NEW.entity_id AND item.active AND item.deprecated_at IS NULL AND state.code='published' AND state.active) THEN RAISE EXCEPTION 'social-event default must reference an active published non-deprecated event type'; END IF; RETURN NEW; END $$"
