  , "CREATE OR REPLACE FUNCTION catalog_prevent_active_social_event_default_deactivation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.active AND NOT NEW.active AND EXISTS (SELECT 1 FROM catalog_scoped_default scoped WHERE scoped.catalog_id=OLD.catalog_id AND scoped.entity_id=OLD.id AND scoped.scope_kind='social-event' AND scoped.scope_id='global' AND scoped.locale_id IS NULL AND scoped.active) THEN RAISE EXCEPTION 'active social-event default cannot be deactivated'; END IF; RETURN NEW; END $$"
