  , "CREATE OR REPLACE FUNCTION catalog_protect_referenced_reaction_type() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.catalog_id IS DISTINCT FROM OLD.catalog_id OR NEW.code IS DISTINCT FROM OLD.code THEN RAISE EXCEPTION 'referenced reaction type catalog and code are immutable' USING ERRCODE='23514'; END IF; IF OLD.active AND NOT NEW.active AND EXISTS (SELECT 1 FROM event_moment_reaction reaction WHERE reaction.reaction_type_id=OLD.id) THEN RAISE EXCEPTION 'a referenced reaction type must be replaced before deactivation' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
