  , "DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['catalog_definition','catalog_backfill_run','catalog_migration_mapping','catalog_slug_alias','catalog_search_alias','catalog_scoped_default','workflow_definition','workflow_state','workflow_transition','workflow_default_state','workflow_state_capability','pipeline_workflow_binding','security_module','security_action','security_permission','security_role','security_role_assignment_policy','security_grant_revision','role_permission','party_security_role','security_audit_event','release_type_reference','recording_type_reference','recording_session_type','service_category','service_pricing_model','service_offering','service_resource_selection_mode','radio_auto_stop_option','appearance_mode_option','service_offering_default_resource','genre','instrument','event_type','booking_type','feedback_category','feedback_severity','content_category','tag','reaction_type','country_reference','subdivision_reference','city_reference','currency_reference','tax_rate_reference','language_reference','locale_reference','external_provider','external_provider_code','ddex_standard_version','ddex_standard_support','ddex_message_type','ddex_vocabulary','ddex_code','ddex_code_applicability','ddex_job_operation','ddex_import_operation','ddex_validation_result','ddex_validation_severity','ddex_validation_layer','ddex_partner','ddex_partner_standard_version','ddex_document','ddex_validation_run','ddex_validation_issue','ddex_import_plan','ddex_import_run','ddex_job','ddex_export','ddex_import_change','content_type','authored_content','record_release','recording','recording_session','editorial_collection','record_contributor','record_external_resource','radio_stream_genre_observation','radio_stream_genre_observation_candidate','radio_stream_country_observation','radio_stream_country_observation_candidate'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS catalog_no_hard_delete ON %I', table_name); EXECUTE format('CREATE TRIGGER catalog_no_hard_delete BEFORE DELETE ON %I FOR EACH ROW EXECUTE FUNCTION catalog_prevent_hard_delete()', table_name); END LOOP; END $$"
  , "CREATE OR REPLACE FUNCTION security_validate_assignment_policy() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE role_allowed boolean; BEGIN IF NEW.trigger_code NOT IN ('account-signup','google-account-create','verified-artist-claim','generated-account-create','course-registration','trial-inquiry','teacher-subject-configured','teacher-student-linked','student-created','artist-profile-created') THEN RAISE EXCEPTION 'unknown automatic security policy trigger' USING ERRCODE='23514'; END IF; IF NEW.effective_from IS NOT NULL AND NEW.effective_to IS NOT NULL AND NEW.effective_to<=NEW.effective_from THEN RAISE EXCEPTION 'automatic security policy effective period is invalid' USING ERRCODE='23514'; END IF; SELECT active AND automatic_assignable AND NOT emergency_administrator INTO role_allowed FROM security_role WHERE id=NEW.role_id; IF NOT COALESCE(role_allowed,FALSE) THEN RAISE EXCEPTION 'automatic security policies require an active, explicitly automatic, non-emergency role' USING ERRCODE='42501'; END IF; IF NEW.created_by IS NOT NULL AND (NEW.approved_by IS NULL OR NEW.approved_by=NEW.created_by) THEN RAISE EXCEPTION 'automatic security policy changes require a distinct approver' USING ERRCODE='42501'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS security_assignment_policy_integrity ON security_role_assignment_policy"
  , "CREATE TRIGGER security_assignment_policy_integrity BEFORE INSERT OR UPDATE ON security_role_assignment_policy FOR EACH ROW EXECUTE FUNCTION security_validate_assignment_policy()"
  , "CREATE OR REPLACE FUNCTION security_validate_party_role_approval() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE is_sensitive boolean; actor_is_emergency boolean; valid_revision boolean; valid_policy boolean; BEGIN IF NEW.approval_mode NOT IN ('normal','emergency','bootstrap','system-policy') THEN RAISE EXCEPTION 'invalid security grant approval mode' USING ERRCODE='23514'; END IF; IF NEW.approval_mode='system-policy' THEN IF NEW.source_policy_id IS NULL OR NEW.source_revision_id IS NOT NULL OR NEW.granted_by IS NOT NULL OR NEW.approved_by IS NOT NULL OR NEW.emergency_reason IS NOT NULL THEN RAISE EXCEPTION 'system-policy grants require policy-only provenance' USING ERRCODE='23514'; END IF; SELECT EXISTS (SELECT 1 FROM security_role_assignment_policy policy JOIN security_role role ON role.id=policy.role_id WHERE policy.id=NEW.source_policy_id AND policy.role_id=NEW.role_id AND policy.active AND role.active AND role.automatic_assignable AND NOT role.emergency_administrator AND (policy.effective_from IS NULL OR policy.effective_from<=CURRENT_TIMESTAMP) AND (policy.effective_to IS NULL OR policy.effective_to>CURRENT_TIMESTAMP)) INTO valid_policy; IF NOT COALESCE(valid_policy,FALSE) OR NOT NEW.active THEN RAISE EXCEPTION 'system-policy grant does not match an effective automatic policy' USING ERRCODE='23514'; END IF; RETURN NEW; END IF; IF NEW.source_policy_id IS NOT NULL THEN RAISE EXCEPTION 'only system-policy grants may reference an assignment policy' USING ERRCODE='23514'; END IF; IF NEW.granted_by IS NOT NULL AND NEW.source_revision_id IS NULL THEN RAISE EXCEPTION 'administrative security grants require an approved source revision' USING ERRCODE='23514'; END IF; IF NEW.granted_by IS NOT NULL THEN SELECT EXISTS (SELECT 1 FROM security_grant_revision revision JOIN workflow_state state ON state.id=revision.workflow_state_id WHERE revision.id=NEW.source_revision_id AND state.code='published' AND revision.approved_at IS NOT NULL AND revision.created_by=NEW.granted_by AND revision.approved_by=NEW.approved_by AND revision.approval_mode=NEW.approval_mode AND COALESCE(revision.emergency_reason,'')=COALESCE(NEW.emergency_reason,'') AND revision.role_id=NEW.role_id AND revision.desired_active=NEW.active AND revision.change_kind='party-role' AND revision.party_id=NEW.party_id AND revision.permission_id IS NULL) INTO valid_revision; IF NOT COALESCE(valid_revision,FALSE) THEN RAISE EXCEPTION 'security grant does not match an approved source revision' USING ERRCODE='23514'; END IF; END IF; SELECT (r.emergency_administrator OR r.system_role) INTO is_sensitive FROM security_role r WHERE r.id=NEW.role_id; IF COALESCE(is_sensitive,FALSE) AND NEW.granted_by IS NOT NULL THEN IF NEW.approved_by IS NULL THEN RAISE EXCEPTION 'sensitive security grants require approval' USING ERRCODE='42501'; ELSIF NEW.approved_by=NEW.granted_by THEN IF NEW.approval_mode<>'emergency' OR length(btrim(COALESCE(NEW.emergency_reason,'')))<20 THEN RAISE EXCEPTION 'sensitive security grants require a distinct approver or documented emergency override' USING ERRCODE='42501'; END IF; SELECT security_is_coherent_emergency_administrator(NEW.approved_by) INTO actor_is_emergency; IF NOT COALESCE(actor_is_emergency,FALSE) THEN RAISE EXCEPTION 'emergency security approver is not active' USING ERRCODE='42501'; END IF; ELSIF NEW.approval_mode<>'normal' OR NEW.emergency_reason IS NOT NULL THEN RAISE EXCEPTION 'non-emergency security approval must use normal mode' USING ERRCODE='23514'; END IF; ELSIF NEW.approval_mode='emergency' THEN RAISE EXCEPTION 'emergency mode is valid only for sensitive grants' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "CREATE OR REPLACE FUNCTION security_validate_role_permission_approval() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE is_sensitive boolean; actor_is_emergency boolean; valid_revision boolean; BEGIN IF NEW.approval_mode NOT IN ('normal','emergency','bootstrap') THEN RAISE EXCEPTION 'invalid security grant approval mode' USING ERRCODE='23514'; END IF; IF NEW.granted_by IS NOT NULL AND NEW.source_revision_id IS NULL THEN RAISE EXCEPTION 'administrative security grants require an approved source revision' USING ERRCODE='23514'; END IF; IF NEW.granted_by IS NOT NULL THEN SELECT EXISTS (SELECT 1 FROM security_grant_revision revision JOIN workflow_state state ON state.id=revision.workflow_state_id WHERE revision.id=NEW.source_revision_id AND state.code='published' AND revision.approved_at IS NOT NULL AND revision.created_by=NEW.granted_by AND revision.approved_by=NEW.approved_by AND revision.approval_mode=NEW.approval_mode AND COALESCE(revision.emergency_reason,'')=COALESCE(NEW.emergency_reason,'') AND revision.role_id=NEW.role_id AND revision.desired_active=NEW.active AND revision.change_kind='role-permission' AND revision.party_id IS NULL AND revision.permission_id=NEW.permission_id) INTO valid_revision; IF NOT COALESCE(valid_revision,FALSE) THEN RAISE EXCEPTION 'security grant does not match an approved source revision' USING ERRCODE='23514'; END IF; END IF; SELECT p.sensitive INTO is_sensitive FROM security_permission p WHERE p.id=NEW.permission_id; IF COALESCE(is_sensitive,FALSE) AND NEW.granted_by IS NOT NULL THEN IF NEW.approved_by IS NULL THEN RAISE EXCEPTION 'sensitive security grants require approval' USING ERRCODE='42501'; ELSIF NEW.approved_by=NEW.granted_by THEN IF NEW.approval_mode<>'emergency' OR length(btrim(COALESCE(NEW.emergency_reason,'')))<20 THEN RAISE EXCEPTION 'sensitive security grants require a distinct approver or documented emergency override' USING ERRCODE='42501'; END IF; SELECT security_is_coherent_emergency_administrator(NEW.approved_by) INTO actor_is_emergency; IF NOT COALESCE(actor_is_emergency,FALSE) THEN RAISE EXCEPTION 'emergency security approver is not active' USING ERRCODE='42501'; END IF; ELSIF NEW.approval_mode<>'normal' OR NEW.emergency_reason IS NOT NULL THEN RAISE EXCEPTION 'non-emergency security approval must use normal mode' USING ERRCODE='23514'; END IF; ELSIF NEW.approval_mode='emergency' THEN RAISE EXCEPTION 'emergency mode is valid only for sensitive grants' USING ERRCODE='23514'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS role_permission_sensitive_approval ON role_permission"
  , "CREATE TRIGGER role_permission_sensitive_approval BEFORE INSERT OR UPDATE ON role_permission FOR EACH ROW EXECUTE FUNCTION security_validate_role_permission_approval()"
  , "DROP TRIGGER IF EXISTS party_security_role_sensitive_approval ON party_security_role"
  , "CREATE TRIGGER party_security_role_sensitive_approval BEFORE INSERT OR UPDATE ON party_security_role FOR EACH ROW EXECUTE FUNCTION security_validate_party_role_approval()"
  , "CREATE OR REPLACE FUNCTION security_party_role_identity_is_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.party_id IS DISTINCT FROM OLD.party_id OR NEW.role_id IS DISTINCT FROM OLD.role_id THEN RAISE EXCEPTION 'party security role identity is immutable' USING ERRCODE='55000'; END IF; IF OLD.source_policy_id IS NOT NULL AND NEW.source_policy_id IS DISTINCT FROM OLD.source_policy_id AND NEW.source_policy_id IS NOT NULL THEN RAISE EXCEPTION 'automatic security assignment policy provenance cannot be replaced by a different policy' USING ERRCODE='55000'; END IF; RETURN NEW; END $$"
  , "CREATE OR REPLACE FUNCTION security_role_permission_identity_is_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.role_id IS DISTINCT FROM OLD.role_id OR NEW.permission_id IS DISTINCT FROM OLD.permission_id THEN RAISE EXCEPTION 'role permission identity is immutable' USING ERRCODE='55000'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS party_security_role_identity_immutable ON party_security_role"
  , "CREATE TRIGGER party_security_role_identity_immutable BEFORE UPDATE ON party_security_role FOR EACH ROW EXECUTE FUNCTION security_party_role_identity_is_immutable()"
  , "DROP TRIGGER IF EXISTS role_permission_identity_immutable ON role_permission"
  , "CREATE TRIGGER role_permission_identity_immutable BEFORE UPDATE ON role_permission FOR EACH ROW EXECUTE FUNCTION security_role_permission_identity_is_immutable()"
  , "CREATE OR REPLACE FUNCTION security_protect_emergency_capability() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE emergency_role boolean; permission_code text; remaining bigint; BEGIN IF NOT OLD.active OR (TG_OP='UPDATE' AND NEW.active) THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF; SELECT emergency_administrator INTO emergency_role FROM security_role WHERE id=OLD.role_id; SELECT code INTO permission_code FROM security_permission WHERE id=OLD.permission_id; IF NOT COALESCE(emergency_role,FALSE) OR permission_code NOT IN ('admin.access','security.read','security.create','security.review','security.approve','security.assign','security.emergency-recover') THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF; SELECT count(DISTINCT assignment.party_id) INTO remaining FROM party_security_role assignment JOIN security_role role ON role.id=assignment.role_id AND role.active AND role.emergency_administrator JOIN user_credential credential ON credential.party_id=assignment.party_id AND credential.active WHERE assignment.active AND NOT EXISTS (SELECT required.code FROM (VALUES ('admin.access'),('security.read'),('security.create'),('security.review'),('security.approve'),('security.assign'),('security.emergency-recover')) required(code) WHERE NOT EXISTS (SELECT 1 FROM role_permission grant_row JOIN security_permission permission ON permission.id=grant_row.permission_id AND permission.active JOIN security_action action ON action.id=permission.action_id AND action.active JOIN security_module module_row ON module_row.id=permission.module_id AND module_row.active WHERE grant_row.role_id=role.id AND grant_row.active AND grant_row.id<>OLD.id AND permission.code=required.code)); IF remaining<1 THEN RAISE EXCEPTION 'cannot remove a capability required by the last coherent emergency administrator' USING ERRCODE='42501'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$"
  , "DROP TRIGGER IF EXISTS role_permission_last_emergency_capability ON role_permission"
  , "CREATE TRIGGER role_permission_last_emergency_capability BEFORE UPDATE OR DELETE ON role_permission FOR EACH ROW EXECUTE FUNCTION security_protect_emergency_capability()"
  , "CREATE OR REPLACE FUNCTION security_protect_last_emergency_admin() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE emergency boolean; remaining bigint; BEGIN SELECT emergency_administrator INTO emergency FROM security_role WHERE id=OLD.role_id; IF NOT COALESCE(emergency,FALSE) OR NOT OLD.active OR (TG_OP='UPDATE' AND NEW.active) THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF; SELECT count(DISTINCT assignment.party_id) INTO remaining FROM party_security_role assignment JOIN security_role role ON role.id=assignment.role_id AND role.active AND role.emergency_administrator JOIN user_credential credential ON credential.party_id=assignment.party_id AND credential.active WHERE assignment.active AND assignment.id<>OLD.id AND NOT EXISTS (SELECT required.code FROM (VALUES ('admin.access'),('security.read'),('security.create'),('security.review'),('security.approve'),('security.assign'),('security.emergency-recover')) required(code) WHERE NOT EXISTS (SELECT 1 FROM role_permission grant_row JOIN security_permission permission ON permission.id=grant_row.permission_id AND permission.active JOIN security_action action ON action.id=permission.action_id AND action.active JOIN security_module module_row ON module_row.id=permission.module_id AND module_row.active WHERE grant_row.role_id=role.id AND grant_row.active AND permission.code=required.code)); IF remaining<1 THEN RAISE EXCEPTION 'cannot remove the last coherent emergency administrator' USING ERRCODE='42501'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$"
  , "DROP TRIGGER IF EXISTS party_security_role_last_emergency_admin ON party_security_role"
  , "CREATE TRIGGER party_security_role_last_emergency_admin BEFORE UPDATE OR DELETE ON party_security_role FOR EACH ROW EXECUTE FUNCTION security_protect_last_emergency_admin()"
  , "CREATE OR REPLACE FUNCTION security_protect_last_emergency_credential() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE remaining bigint; BEGIN IF NOT OLD.active OR (TG_OP='UPDATE' AND NEW.active) OR NOT EXISTS (SELECT 1 FROM party_security_role assignment JOIN security_role role ON role.id=assignment.role_id WHERE assignment.party_id=OLD.party_id AND assignment.active AND role.active AND role.emergency_administrator) THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF; SELECT count(DISTINCT assignment.party_id) INTO remaining FROM party_security_role assignment JOIN security_role role ON role.id=assignment.role_id AND role.active AND role.emergency_administrator JOIN user_credential credential ON credential.party_id=assignment.party_id AND credential.active AND credential.id<>OLD.id WHERE assignment.active AND NOT EXISTS (SELECT required.code FROM (VALUES ('admin.access'),('security.read'),('security.create'),('security.review'),('security.approve'),('security.assign'),('security.emergency-recover')) required(code) WHERE NOT EXISTS (SELECT 1 FROM role_permission grant_row JOIN security_permission permission ON permission.id=grant_row.permission_id AND permission.active JOIN security_action action ON action.id=permission.action_id AND action.active JOIN security_module module_row ON module_row.id=permission.module_id AND module_row.active WHERE grant_row.role_id=role.id AND grant_row.active AND permission.code=required.code)); IF remaining<1 THEN RAISE EXCEPTION 'cannot remove the last coherent emergency administrator credential' USING ERRCODE='42501'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$"
  , "DROP TRIGGER IF EXISTS user_credential_last_emergency_admin ON user_credential"
  , "CREATE TRIGGER user_credential_last_emergency_admin BEFORE UPDATE OF active OR DELETE ON user_credential FOR EACH ROW EXECUTE FUNCTION security_protect_last_emergency_credential()"
  , "CREATE OR REPLACE FUNCTION security_protect_last_emergency_role() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE remaining bigint; BEGIN IF NOT OLD.active OR NOT OLD.emergency_administrator OR (NEW.active AND NEW.emergency_administrator) THEN RETURN NEW; END IF; SELECT count(DISTINCT assignment.party_id) INTO remaining FROM party_security_role assignment JOIN security_role role ON role.id=assignment.role_id AND role.id<>OLD.id AND role.active AND role.emergency_administrator JOIN user_credential credential ON credential.party_id=assignment.party_id AND credential.active WHERE assignment.active AND NOT EXISTS (SELECT required.code FROM (VALUES ('admin.access'),('security.read'),('security.create'),('security.review'),('security.approve'),('security.assign'),('security.emergency-recover')) required(code) WHERE NOT EXISTS (SELECT 1 FROM role_permission grant_row JOIN security_permission permission ON permission.id=grant_row.permission_id AND permission.active JOIN security_action action ON action.id=permission.action_id AND action.active JOIN security_module module_row ON module_row.id=permission.module_id AND module_row.active WHERE grant_row.role_id=role.id AND grant_row.active AND permission.code=required.code)); IF remaining<1 THEN RAISE EXCEPTION 'cannot disable the last coherent emergency administrator role' USING ERRCODE='42501'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS security_role_last_emergency_admin ON security_role"
  , "CREATE TRIGGER security_role_last_emergency_admin BEFORE UPDATE OF active, emergency_administrator ON security_role FOR EACH ROW EXECUTE FUNCTION security_protect_last_emergency_role()"
  , "CREATE OR REPLACE FUNCTION security_protect_emergency_registry_activation() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE remaining bigint; BEGIN IF NOT OLD.active OR NEW.active THEN RETURN NEW; END IF; SELECT count(DISTINCT assignment.party_id) INTO remaining FROM party_security_role assignment JOIN security_role role ON role.id=assignment.role_id AND role.active AND role.emergency_administrator JOIN user_credential credential ON credential.party_id=assignment.party_id AND credential.active WHERE assignment.active AND NOT EXISTS (SELECT required.code FROM (VALUES ('admin.access'),('security.read'),('security.create'),('security.review'),('security.approve'),('security.assign'),('security.emergency-recover')) required(code) WHERE NOT EXISTS (SELECT 1 FROM role_permission grant_row JOIN security_permission permission ON permission.id=grant_row.permission_id AND permission.active AND (TG_TABLE_NAME<>'security_permission' OR permission.id<>OLD.id) JOIN security_action action ON action.id=permission.action_id AND action.active AND (TG_TABLE_NAME<>'security_action' OR action.id<>OLD.id) JOIN security_module module_row ON module_row.id=permission.module_id AND module_row.active AND (TG_TABLE_NAME<>'security_module' OR module_row.id<>OLD.id) WHERE grant_row.role_id=role.id AND grant_row.active AND permission.code=required.code)); IF remaining<1 THEN RAISE EXCEPTION 'cannot deactivate security registry data required by the last coherent emergency administrator' USING ERRCODE='42501'; END IF; RETURN NEW; END $$"
  , "DROP TRIGGER IF EXISTS security_permission_last_emergency_admin ON security_permission"
  , "CREATE TRIGGER security_permission_last_emergency_admin BEFORE UPDATE OF active ON security_permission FOR EACH ROW EXECUTE FUNCTION security_protect_emergency_registry_activation()"
  , "DROP TRIGGER IF EXISTS security_action_last_emergency_admin ON security_action"
  , "CREATE TRIGGER security_action_last_emergency_admin BEFORE UPDATE OF active ON security_action FOR EACH ROW EXECUTE FUNCTION security_protect_emergency_registry_activation()"
  , "DROP TRIGGER IF EXISTS security_module_last_emergency_admin ON security_module"
  , "CREATE TRIGGER security_module_last_emergency_admin BEFORE UPDATE OF active ON security_module FOR EACH ROW EXECUTE FUNCTION security_protect_emergency_registry_activation()"
  ]
